import math

def test_clips_long_vector():
    got = solution.clip_gradient([3.0, 4.0], 1.0)
    assert abs(got[0] - 0.6) < 1e-12
    assert abs(got[1] - 0.8) < 1e-12

def test_empty():
    assert solution.clip_gradient([], 1.0) == []

def test_short_untouched():
    assert solution.clip_gradient([0.3, 0.4], 1.0) == [0.3, 0.4]

def test_result_norm():
    got = solution.clip_gradient([6.0, 8.0], 0.5)
    assert abs(math.sqrt(sum(x * x for x in got)) - 0.5) < 1e-12
    assert abs(got[0] / got[1] - 0.75) < 1e-12

def test_bad_max_norm_raises():
    for m in (0.0, -1.0):
        try:
            solution.clip_gradient([1.0], m)
        except ValueError:
            continue
        raise AssertionError("expected ValueError for max_norm=%r" % (m,))

def test_no_mutation():
    g = [3.0, 4.0]
    solution.clip_gradient(g, 1.0)
    assert g == [3.0, 4.0]
